#!/usr/bin/env python3
"""Compare an explicit checkpoint schedule with complete native JSON trees.

This checks checkpoint trees only. It does not certify responses, continuous
execution, input completeness, EVM prestate identity, or source/binary provenance.
"""
import argparse
import json
from pathlib import Path
import sys


def canonical(value):
    # Preserve JSON scalar types (Python's True == 1 must not count as parity).
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)


def verify(report_dir, native_paths, heights, chain):
    if not heights or any(type(h) is not int or h < 0 for h in heights):
        raise ValueError("expected heights must be a nonempty list of nonnegative integers")
    if sorted(set(heights)) != heights:
        raise ValueError("expected heights must be unique and ascending")
    expected = set(heights)
    truth = {}
    duplicates = 0
    for path in native_paths:
        with path.open() as stream:
            for line_number, line in enumerate(stream, 1):
                if not line.strip():
                    continue
                record = json.loads(line)
                height = record.get("height")
                if type(height) is not int or height not in expected:
                    continue
                if record.get("chain") != chain:
                    raise ValueError(f"wrong chain at {path}:{line_number}")
                tree = record.get("exchange_abci_hash")
                digest = record.get("abci_digest")
                if not isinstance(tree, list) or not tree or not isinstance(digest, str):
                    raise ValueError(f"incomplete native checkpoint {height}")
                identity = (canonical(tree), digest)
                if height in truth:
                    if truth[height]["identity"] != identity:
                        raise ValueError(f"conflicting native checkpoints at height {height}")
                    duplicates += 1
                else:
                    truth[height] = {"identity": identity, "path": str(path), "line": line_number}
    missing_truth = sorted(expected - truth.keys())
    if missing_truth:
        raise ValueError(f"missing native checkpoint heights: {missing_truth}")
    report_paths = {}
    for path in report_dir.glob("abci_tree_*.json"):
        height = int(path.stem.removeprefix("abci_tree_"))
        report_paths[height] = path
    if set(report_paths) != expected:
        raise ValueError(f"report height set differs: missing={sorted(expected - report_paths.keys())}, "
                         f"extra={sorted(report_paths.keys() - expected)}")
    failures = []
    for height in heights:
        actual = json.loads(report_paths[height].read_text())
        if canonical(actual) != truth[height]["identity"][0]:
            failures.append(height)
    if failures:
        raise ValueError(f"native checkpoint tree mismatch at heights: {failures}")
    return {"scope": "checkpoint-tree-equality-only", "chain": chain,
            "expected_heights": heights, "exact_checkpoints": len(heights),
            "identical_native_duplicates": duplicates, "continuous_execution_certified": False,
            "truth_sources": [{"height": h, "path": truth[h]["path"],
                               "line": truth[h]["line"]} for h in heights]}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--report-dir", required=True, type=Path)
    parser.add_argument("--native-hashes", required=True, type=Path,
                        help="native JSON-lines file or directory of files")
    parser.add_argument("--expected-heights", required=True, type=Path,
                        help="JSON array of every required checkpoint height")
    parser.add_argument("--chain", required=True)
    args = parser.parse_args()
    try:
        paths = ([args.native_hashes] if args.native_hashes.is_file() else
                 sorted(p for p in args.native_hashes.rglob("*") if p.is_file()))
        result = verify(args.report_dir, paths, json.loads(args.expected_heights.read_text()), args.chain)
        print(json.dumps(result, indent=2))
        return 0
    except (ValueError, TypeError, OSError) as error:
        print(json.dumps({"scope": "checkpoint-tree-equality-only", "error": str(error),
                          "continuous_execution_certified": False}), file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
